<template><div class="zero-hour-detail"><AppPageHeader title="零星用工详情" description="基本信息、成本构成与独立财务明细"/><AppWorkspacePanel v-if="detail"><el-descriptions border :column="isMobile?1:2"><el-descriptions-item label="用工日期">{{detail.labor.labor_date}}</el-descriptions-item><el-descriptions-item label="派工单位">{{detail.labor.dispatch_unit||'-'}}</el-descriptions-item><el-descriptions-item label="归属">{{detail.labor.attribution==='PROJECT'?'项目用工':'公司用工'}}</el-descriptions-item><el-descriptions-item label="关联合同">{{detail.labor.upstream_contract?.contract_name||'-'}}</el-descriptions-item><el-descriptions-item label="说明">{{detail.labor.description||'-'}}</el-descriptions-item><el-descriptions-item label="审批状态">{{detail.labor.approval_status||'-'}}</el-descriptions-item><el-descriptions-item label="审批文件"><el-button v-if="detail.labor.approval_pdf_key" link type="primary" @click="viewFile(detail.labor.approval_pdf_key)">查看审批文件</el-button><span v-else>-</span></el-descriptions-item></el-descriptions><section class="cost-grid"><div><span>技工</span><strong>¥ {{detail.labor.skilled_price_total}}</strong></div><div><span>普工</span><strong>¥ {{detail.labor.general_price_total}}</strong></div><div><span>车辆</span><strong>¥ {{detail.labor.vehicle_price_total}}</strong></div><div><span>材料</span><strong>¥ {{detail.labor.material_price_total}}</strong></div></section><div class="finance-summary"><el-statistic title="应付款" :value="detail.payable_total"/><el-statistic title="已挂账" :value="detail.invoiced_total"/><el-statistic title="已付款" :value="detail.paid_total"/><el-statistic title="未付款" :value="Number(detail.payable_total)-Number(detail.paid_total)"/></div><el-tabs v-model="tab"><el-tab-pane v-for="meta in sections" :key="meta.kind" :label="meta.label" :name="meta.kind"><div class="table-toolbar"><el-button type="primary" plain @click="edit(meta.kind)">新增{{meta.singular}}</el-button></div><el-table :data="detail[meta.kind]" border><el-table-column v-for="column in meta.columns" :key="column.prop" :prop="column.prop" :label="column.label"><template v-if="column.prop==='file_key'" #default="{row}"><el-button v-if="row.file_key" link type="primary" @click="viewFile(row.file_key)">查看文件</el-button><span v-else>-</span></template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="edit(meta.kind,row)">编辑</el-button><el-button link type="danger" @click="remove(meta.kind,row)">删除</el-button></template></el-table-column></el-table></el-tab-pane></el-tabs></AppWorkspacePanel><el-dialog v-model="dialog" :title="form.id?'编辑财务明细':'新增财务明细'" width="520px" append-to-body><el-form :model="form" label-width="90px"><el-form-item v-for="field in currentFields" :key="field.key" :label="field.label"><el-date-picker v-if="field.type==='date'" v-model="form[field.key]" value-format="YYYY-MM-DD" style="width:100%"/><el-input-number v-else-if="field.type==='number'" v-model="form[field.key]" :min="0" :precision="2" style="width:100%"/><el-input v-else v-model="form[field.key]"/></el-form-item><el-form-item label="附件/凭证"><el-upload :auto-upload="false" :show-file-list="false" :on-change="uploadAttachment"><el-button :loading="uploading">{{form.file_key?'替换文件':'选择文件'}}</el-button></el-upload><span v-if="form.file_key" class="file-ready">已上传</span></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{useRoute}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{createZeroHourFinance,deleteZeroHourFinance,fetchZeroHourFinanceFile,getZeroHourLaborDetail,updateZeroHourFinance}from'@/api/zeroHourLabor';import{uploadFile}from'@/api/common';import AppPageHeader from'@/components/ui/AppPageHeader.vue';import AppWorkspacePanel from'@/components/ui/AppWorkspacePanel.vue';const route=useRoute(),detail=ref(null),tab=ref('payables'),dialog=ref(false),kind=ref('payables'),uploading=ref(false),isMobile=window.innerWidth<768,form=reactive({});const sections=[{kind:'payables',label:'应付款',singular:'应付款',columns:[{prop:'category',label:'类别'},{prop:'expected_date',label:'预计日期'},{prop:'amount',label:'金额'},{prop:'file_key',label:'审批附件'}]},{kind:'invoices',label:'挂账',singular:'挂账',columns:[{prop:'invoice_number',label:'发票号码'},{prop:'invoice_date',label:'日期'},{prop:'supplier',label:'供应商'},{prop:'amount',label:'金额'},{prop:'status',label:'状态'},{prop:'file_key',label:'来源文件'}]},{kind:'payments',label:'付款',singular:'付款',columns:[{prop:'payment_date',label:'付款日期'},{prop:'payee_name',label:'收款方'},{prop:'payment_method',label:'方式'},{prop:'amount',label:'金额'},{prop:'status',label:'状态'},{prop:'file_key',label:'凭证'}]}];const fields={payables:[['category','类别'],['expected_date','预计日期','date'],['amount','金额','number'],['description','说明']],invoices:[['invoice_number','发票号码'],['invoice_date','挂账日期','date'],['supplier','供应商'],['amount','金额','number'],['tax_amount','税额','number']],payments:[['payment_date','付款日期','date'],['payee_name','收款方'],['payee_account','账号'],['payee_bank','银行'],['payment_method','付款方式'],['amount','金额','number']]};const currentFields=computed(()=>(fields[kind.value]||[]).map(([key,label,type='text'])=>({key,label,type})));const load=async()=>detail.value=await getZeroHourLaborDetail(route.params.id);onMounted(load);const edit=(next,row={})=>{kind.value=next;for(const key of Object.keys(form))delete form[key];Object.assign(form,row,{amount:Number(row.amount||0)});dialog.value=true};const uploadAttachment=async file=>{uploading.value=true;try{const result=await uploadFile(file.raw,{uploadDir:'expenses',subdir:`zero-hour-labor/${route.params.id}`});form.file_path=result.path;form.file_key=result.key;ElMessage.success('文件已上传')}finally{uploading.value=false}};const viewFile=async key=>{const win=window.open('about:blank','_blank');if(!win){ElMessage.error('请允许本站弹出窗口');return}try{const blob=await fetchZeroHourFinanceFile(key);const url=URL.createObjectURL(blob);win.opener=null;win.location.replace(url);window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(error){win.close();throw error}};const save=async()=>{const payload={file_path:form.file_path||null,file_key:form.file_key||null};for(const field of currentFields.value)payload[field.key]=form[field.key];if(form.id)await updateZeroHourFinance(route.params.id,kind.value,form.id,payload);else await createZeroHourFinance(route.params.id,kind.value,payload);ElMessage.success('财务明细已保存');dialog.value=false;await load()};const remove=async(next,row)=>{try{await ElMessageBox.confirm('确定删除该财务明细？','删除确认',{type:'warning'});await deleteZeroHourFinance(route.params.id,next,row.id);ElMessage.success('财务明细已删除');await load()}catch{}}</script>
<style scoped>.finance-summary,.cost-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:24px 0}.cost-grid div{display:flex;justify-content:space-between;padding:14px;border:1px solid var(--el-border-color-light);border-radius:8px}.table-toolbar{display:flex;justify-content:flex-end;margin-bottom:12px}.file-ready{margin-left:10px;color:var(--el-color-success);font-size:13px}@media(max-width:640px){.finance-summary,.cost-grid{grid-template-columns:repeat(2,1fr)}}</style>
